from collections import deque, Counter
def f(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in range(w):
            if i in(0,h-1) or j in(0,w-1):
                if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==bg and not seen[a][b]:
                seen[a][b]=True; q.append((a,b))
    out=[r[:] for r in g]
    # enclosed background components
    vis=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j] and not vis[i][j]:
                comp=[]; q=deque([(i,j)]); vis[i][j]=True
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<h and 0<=y<w and g[x][y]==bg and not seen[x][y] and not vis[x][y]:
                            vis[x][y]=True; q.append((x,y))
                rs=[c[0] for c in comp]; cs=[c[1] for c in comp]
                hh=len(set(rs)); ww=len(set(cs)); area=len(comp)
                fill=7 if area%2==1 else 2
                for a,b in comp: out[a][b]=fill
    return out
